package collector

import (
	"encoding/json"
	"os"
	"reflect"
	"sort"
	"testing"

	"github.com/munakata-hisashi/cliv/internal/model"
)

// Expected inventories are reviewed fixtures, not generated by the parsers.
func TestCollectionFixtures(t *testing.T) {
	cases := []struct {
		name, input string
		parse       func([]byte) ([]model.CLIEntry, error)
	}{
		{"brew", "brew.input.json", func(b []byte) ([]model.CLIEntry, error) { return parseBrew(b, false) }},
		{"brew-all", "brew.input.json", func(b []byte) ([]model.CLIEntry, error) { return parseBrew(b, true) }},
		{"mise", "mise.input.json", parseMise},
		{"npm", "npm.input.json", parseNPM},
		{"uv", "uv.input.txt", parseUV},
		{"cargo", "cargo.input.txt", parseCargo},
		{"go", "go.input.txt", parseGoVersion},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			input, err := os.ReadFile("testdata/" + c.input)
			if err != nil {
				t.Fatal(err)
			}
			data, err := os.ReadFile("testdata/" + c.name + ".expected.json")
			if err != nil {
				t.Fatal(err)
			}
			var expected []model.CLIEntry
			if err := json.Unmarshal(data, &expected); err != nil {
				t.Fatal(err)
			}
			actual, err := c.parse(input)
			if err != nil {
				t.Fatal(err)
			}
			sortInventory := func(entries []model.CLIEntry) {
				sort.Slice(entries, func(i, j int) bool {
					if entries[i].Tool != entries[j].Tool {
						return entries[i].Tool < entries[j].Tool
					}
					return entries[i].Version < entries[j].Version
				})
			}
			sortInventory(expected)
			sortInventory(actual)
			if !reflect.DeepEqual(actual, expected) {
				t.Fatalf("inventory mismatch\nactual: %+v\nexpected: %+v", actual, expected)
			}
		})
	}
}
